$users = Import-Csv C:\new\users.csv
foreach ($u in $users) {
  New-ADUser -Name $u.Name -SamAccountName $u.Sam -Path 'OU=Users,DC=corp,DC=lab' -AccountPassword (ConvertTo-SecureString $u.TempPass -AsPlainText -Force) -Enabled $true -WhatIf
}
# Remove -WhatIf after review, pilot 5, then full run

# Weekly stale-privileged report:
$cutoff=(Get-Date).AddDays(-90)
Get-ADUser -Filter {Enabled -eq $true} -Properties LastLogonDate | Where {$_.LastLogonDate -lt $cutoff -and $_.AdminCount -eq 1}
